<style>
  body {
    margin: 0;
    padding: 0;
    background: #1a1512;
    display: flex;
    justify-content: center;
  }

  .poster {
    width: 620px;
    min-height: 1700px;
    background: #1a1512;
    color: #f0a03c;
    font-family: 'Arial Narrow', Arial, sans-serif;
    text-align: center;
    box-sizing: border-box;
    padding: 22px 15px 30px 15px;
    border: 1px solid #333;
  }

  .header-small {
    font-size: 22px;
    font-weight: 700;
    letter-spacing: 1px;
    color: #f0a03c;
    margin-bottom: 4px;
  }

  .header-medium {
    font-size: 34px;
    font-weight: 900;
    letter-spacing: 1px;
    color: #f0a03c;
    margin: 2px 0;
  }

  .header-small2 {
    font-size: 22px;
    font-weight: 700;
    letter-spacing: 1px;
    color: #f0a03c;
    margin-bottom: 20px;
  }

  .title-block {
    font-weight: 900;
    font-size: 84px;
    line-height: 0.95;
    color: #f0a03c;
    letter-spacing: 1px;
    margin: 10px 0 20px 0;
    font-family: 'Arial Black', Arial, sans-serif;
  }

  .subtitle {
    font-size: 22px;
    font-weight: 700;
    color: #f0a03c;
    line-height: 1.3;
    margin-bottom: 20px;
  }

  .placeholder {
    width: 100%;
    height: 620px;
    background: linear-gradient(to bottom, #e04a1a 0%, #f0a020 100%);
    color: #1a1512;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    font-weight: 700;
    font-size: 16px;
    box-sizing: border-box;
    margin: 0 auto 25px auto;
    position: relative;
    overflow: hidden;
  }

  .placeholder .caption {
    position: absolute;
    bottom: 8px;
    width: 100%;
    color: #3a2a1a;
    font-size: 13px;
    font-style: italic;
  }

  .placeholder-text {
    position: absolute;
    top: 15px;
    left: 0;
    width: 100%;
    padding: 0 10px;
    box-sizing: border-box;
    text-align: left;
  }

  .placeholder-text .line1 {
    font-family: 'Arial Black', Arial, sans-serif;
    font-size: 46px;
    font-weight: 900;
    color: #1a1512;
    line-height: 1;
    letter-spacing: -1px;
  }

  .placeholder-text .line1 .to-the {
    font-size: 20px;
    vertical-align: middle;
  }

  .placeholder-text .line2 {
    font-family: 'Arial Black', Arial, sans-serif;
    font-size: 38px;
    font-weight: 900;
    color: #1a1512;
    line-height: 1.05;
    letter-spacing: -1px;
    margin-top: 5px;
  }

  .placeholder-text .line3 {
    font-family: 'Arial Black', Arial, sans-serif;
    font-size: 33px;
    font-weight: 900;
    color: #1a1512;
    line-height: 1.05;
    letter-spacing: -1px;
  }

  .figure-area {
    position: absolute;
    bottom: 0;
    width: 100%;
    height: 68%;
    background: repeating-linear-gradient(
      45deg,
      #2a2018,
      #2a2018 4px,
      #332618 4px,
      #332618 8px
    );
  }

  .dates {
    font-size: 30px;
    font-weight: 900;
    color: #f0a03c;
    margin-bottom: 6px;
  }

  .schedule {
    font-size: 21px;
    font-weight: 700;
    color: #f0a03c;
    line-height: 1.4;
  }

  .schedule sup, .schedule .small-pm {
    font-size: 13px;
  }

  .opening {
    font-size: 30px;
    font-weight: 900;
    color: #f0a03c;
    margin-top: 15px;
  }

  .opening-time {
    font-size: 22px;
    font-weight: 700;
    color: #f0a03c;
    margin-top: 2px;
  }

  .footer-note {
    font-size: 11px;
    letter-spacing: 1px;
    color: #d99a55;
    margin-top: 25px;
  }
</style>
</head>
