  <div class="schedule">
    MONDAY-FRIDAY 10 - 4:30<span class="small-pm">PM</span><br>
    SATURDAY AND SUNDAY 12 - 5<span class="small-pm">PM</span>
  </div>

  <div class="opening">OPENING</div>
  <div class="opening-time">FRIDAY NOV 4<sup>TH</sup> &nbsp;&nbsp; 7 - 11 <span class="small-pm">PM</span></div>

